SELECT 
FROM admin


        is_deleted = #{dto.isDeleted}


        AND username = #{dto.username}


        AND username LIKE CONCAT('%',#{dto.usernameLike},'%')


        AND real_name LIKE CONCAT('%',#{dto.realNameLike},'%')


        AND phone = #{dto.phone}


        AND status = #{dto.status}


        AND role_id = #{dto.roleId}


        AND create_time >= #{dto.createTimeStart}


        AND create_time <= #{dto.createTimeEnd}


        AND last_login_time >= #{dto.lastLoginTimeStart}


        AND last_login_time <= #{dto.lastLoginTimeEnd}


ORDER BY id ASC
LIMIT #{offset}, #{dto.size}

